select case when year(last_restock) < 2024 then 'before_2024' when year(last_restock) = 2024 then '2024' else 'after_2024' end as last_restock_cohort, max(quantity) as max_quantity, count(distinct quantity) as unique_products, round(stddev(quantity), 2) as stddev_quantity from inventory where product_id = 9 and last_restock between '2023-05-01' and '2023-09-27' and store_id in (1, 3, 5) group by case when year(last_restock) < 2024 then 'before_2024' when year(last_restock) = 2024 then '2024' else 'after_2024' end having max_quantity < 220 order by unique_products desc, last_restock_cohort
